G=load(); print(sorted(G))
def f(g):
    from collections import Counter
    c=Counter(v for r in g for v in r).most_common()
    bg=c[-1][0]  # less frequent = background
    rows={i for i,r in enumerate(g) if set(r)=={bg}}
    cols={j for j in range(len(g[0])) if all(r[j]==bg for r in g)}
    return [[2 if (v==bg and (i in rows or j in cols)) else v for j,v in enumerate(r)] for i,r in enumerate(g)]
